// The webhook path is optional: a publication signal is enough reason to
// drain the queue. When the shared webhook secret is configured, reject a
// caller that cannot present it, then hand a bounded batch size downstream.
const input = $input.first();
const headers = input?.json?.headers ?? {};
const expectedSecret = $env.XASS_ASSESSMENT_WEBHOOK_SECRET;

if (expectedSecret) {
  const provided = headers['x-xass-assessment-webhook-secret'] ?? headers['X-Xass-Assessment-Webhook-Secret'];
  if (provided !== expectedSecret) {
    throw new Error('Invalid X-Assurance assessment webhook secret.');
  }
}

const limit = Number.isInteger($env.XASS_ASSESSMENT_BATCH_LIMIT)
  ? Number($env.XASS_ASSESSMENT_BATCH_LIMIT)
  : 5;

return [{ json: { limit } }];
